const response = $input.first().json || {};
const content = response.content
  ?.filter((part) => part.type === 'text')
  .map((part) => part.text)
  .join('\n')
  .trim() || '';

let parsed = null;

if (content) {
  let cleaned = content
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();

  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace > firstBrace) {
    cleaned = cleaned.slice(firstBrace, lastBrace + 1);
  }

  try {
    parsed = JSON.parse(cleaned);
  } catch {
    parsed = null;
  }
}

if (!parsed || typeof parsed !== 'object') {
  const prepared = $('Prepare - Judge Body').first().json || {};
  parsed = {
    decision:
      prepared.preCalculatedDecision ||
      'NOTIFY_ONLY',
    confidenceScore: 80,
    securityLevel: 'HIGH',
    errorsSummary:
      'Judge response could not be parsed; deterministic decision retained.',
    cicdIssues: '',
    securityIssues: '',
    agentActions: '',
    developerActions: '',
    recommendations:
      prepared.preCalculatedReason ||
      'Review the generated reports.',
    fallbackUsed: true,
  };
}

const allowedDecisions = new Set([
  'AUTO_FIX',
  'BLOCK',
  'NOTIFY_ONLY',
]);

const decision = String(parsed.decision || '')
  .trim()
  .toUpperCase();

parsed.decision = allowedDecisions.has(decision)
  ? decision
  : String(
      $('Prepare - Judge Body').first().json.preCalculatedDecision ||
      'NOTIFY_ONLY'
    ).toUpperCase();

const confidence = Number(parsed.confidenceScore ?? 0);
parsed.confidenceScore = Number.isFinite(confidence)
  ? Math.max(0, Math.min(100, confidence))
  : 0;

parsed.securityLevel = String(
  parsed.securityLevel ||
  parsed.security_level ||
  'HIGH'
).toUpperCase();

return [{ json: parsed }];

const judge = $('Judge - Parse Output').first().json || {};
const incident = $('Extract Project Config').first().json || {};
const enriched =
  $('Merge All Fetched Data').first().json.enrichedData || {};
const combined = $('Merge Agent Reports').first().json || {};

const decision = String(
  judge.decision || 'NOTIFY_ONLY'
).toUpperCase();

const securityLevel = String(
  judge.securityLevel ||
  judge.security_level ||
  'LOW'
).toUpperCase();

const decisionToStatus = {
  BLOCK: 'blocked',
  AUTO_FIX: 'analyzed',
  NOTIFY_ONLY: 'analyzed',
};

const statusForBackend =
  decisionToStatus[decision] || 'analyzed';

const computeScore = (level, dec) => {
  if (level === 'CRITICAL' || dec === 'BLOCK') return 10;
  if (level === 'HIGH') return 30;
  if (level === 'MEDIUM') return 60;
  if (level === 'LOW' && dec === 'AUTO_FIX') return 75;
  return 90;
};

const incidentUUID =
  $('Prepare Fetch URLs').first().json.incidentUUID ||
  incident.incidentUUID ||
  incident.incidentId ||
  null;

const aiSummaryObject = {
  build: enriched.build?.number || null,
  job: enriched.build?.job || null,
  status: enriched.build?.status || null,
  ...judge,
};

return [{
  json: {
    incidentUUID,
    type: 'combined',
    projectId: incident.projectId || null,
    aiSummary: JSON.stringify(aiSummaryObject),
    aiAnalysisObject: aiSummaryObject,
    statusForBackend,
    rawData: {
      rootCause: combined.rootCauseAnalysis || {},
      security: combined.securityRiskAnalysis || {},
      remediation: combined.remediationAnalysis || {},
      enrichedData: enriched,
    },
    securityScore: computeScore(
      securityLevel,
      decision
    ),
    riskLevel: securityLevel.toLowerCase(),
    decision,
    backendBaseUrl:
      incident.backendUrl ||
      'http://172.31.172.61:3001',
    githubRepo: incident.githubRepo || null,
    branch: incident.branch || 'main',
  },
}];

const prepared = $('Prepare - Judge Body').first().json || {};
let payload = {};

try {
  payload = JSON.parse(prepared.judgeInput || '{}');
} catch {
  payload = {};
}

const decision = String(
  prepared.preCalculatedDecision ||
  payload.preCalculatedDecision ||
  'NOTIFY_ONLY'
).toUpperCase();

const criticalCves =
  payload.decisionContext?.vulnerabilitySummary?.criticalCves || 0;
const sonarBlockers =
  payload.decisionContext?.vulnerabilitySummary?.sonarBlockers || 0;
const sonarCriticalVulns =
  payload.decisionContext?.vulnerabilitySummary?.sonarCriticalVulns || 0;

const securityLevel =
  criticalCves > 0 || sonarBlockers > 0 || sonarCriticalVulns > 0
    ? 'CRITICAL'
    : decision === 'AUTO_FIX'
      ? 'HIGH'
      : 'MEDIUM';

const fallbackResult = {
  decision,
  confidenceScore: 90,
  securityLevel,
  errorsSummary:
    'Judge API unavailable; deterministic platform decision was applied.',
  cicdIssues:
    payload.rootCauseAnalysis?.analysisSummary ||
    payload.rootCauseAnalysis?.rootCause ||
    'See enriched pipeline data.',
  securityIssues:
    payload.securityRiskAnalysis?.securitySummary ||
    'See scanner findings.',
  agentActions:
    'Root-cause, security, and remediation agents were evaluated before fallback.',
  developerActions:
    Array.isArray(payload.remediationAnalysis?.fixSteps)
      ? payload.remediationAnalysis.fixSteps.join(' | ')
      : payload.remediationAnalysis?.fixDescription ||
        'Review the remediation report.',
  recommendations:
    `Deterministic fallback used: ${prepared.preCalculatedReason || 'no reason available'}`,
  fallbackUsed: true,
};

return [{
  json: {
    content: [
      {
        type: 'text',
        text: JSON.stringify(fallbackResult),
      },
    ],
  },
}];

const incident = $('Extract Project Config').first().json || {};
const finalReport = $('Prepare Final Report').first().json || {};
const enriched =
  $('Merge All Fetched Data').first().json.enrichedData || {};
const judge = $('Judge - Parse Output').first().json || {};

const incidentId =
  finalReport.incidentUUID ||
  incident.incidentUUID ||
  incident.incidentId ||
  '';

const payload = {
  incidentId,
  projectId:
    finalReport.projectId ||
    incident.projectId ||
    '',
  githubRepo:
    finalReport.githubRepo ||
    incident.githubRepo ||
    '',
  branch:
    finalReport.branch ||
    incident.branch ||
    'main',
  sonarIssues:
    enriched.sonar?.issues || [],
  aiAnalysis: judge,
  decision:
    finalReport.decision ||
    judge.decision ||
    '',
  confidenceScore:
    Number(judge.confidenceScore ?? 0),
  riskLevel:
    finalReport.riskLevel ||
    String(judge.securityLevel || 'low').toLowerCase(),
  backendBaseUrl:
    finalReport.backendBaseUrl ||
    incident.backendUrl ||
    'http://172.31.172.61:3001',
};

if (!payload.incidentId) {
  throw new Error(
    'WF1 cannot call WF2: incidentId is missing'
  );
}

if (!payload.githubRepo) {
  throw new Error(
    'WF1 cannot call WF2: githubRepo is missing'
  );
}

return [{
  json: {
    incidentData: JSON.stringify(payload),
  },
}];

const finalReport = $('Prepare Final Report').first().json || {};

return [{
  json: {
    success: true,
    incidentId: finalReport.incidentUUID || null,
    decision: finalReport.decision || 'NOTIFY_ONLY',
    status: finalReport.statusForBackend || 'analyzed',
    riskLevel: finalReport.riskLevel || 'unknown',
    securityScore: finalReport.securityScore ?? null,
    message:
      finalReport.decision === 'BLOCK'
        ? 'Incident blocked; no automatic patch was created.'
        : 'Analysis completed; no automatic patch was required.',
  },
}];
